/bin/bash -lc "python - <<'PY'
import json, urllib.request
for repo in ['scikit-learn','scikit_learn','sklearn']:
 try:
  u=f'https://quay.io/api/v1/repository/biocontainers/{repo}/tag/?limit=10&page=1'
  with urllib.request.urlopen(u,timeout=20) as r:d=json.load(r)
  print(repo,[t['name'] for t in d.get('tags',[])[:8]])
 except Exception as e: print(repo,type(e).__name__)
PY"

